const telegram = $("Telegram Trigger").first().json;

const chatId = telegram.message.chat.id;
const messageText = (telegram.message.text || "").trim();
const lowerText = messageText.toLowerCase();

const staticData = $getWorkflowStaticData("global");

if (!staticData.leadSessions) {
  staticData.leadSessions = {};
}

const startWords = ["hi", "hello", "hey", "/start", "start", "اهلا", "أهلا", "مرحبا", "هاي"];

// ===============================
// Questions
// ===============================

const questions = [
  {
    key: "business_type",
    text: `Question 1/10
What type of business do you have?

1) Small/local business
2) Growing business
3) Established business with active sales`
  },
  {
    key: "problem",
    text: `Question 2/10
What problem do you want to solve?

1) Just exploring automation
2) Repetitive customer messages
3) Losing leads or sales because of slow follow-up`
  },
  {
    key: "lead_source",
    text: `Question 3/10
Where do your leads come from?

1) Not sure / no regular leads
2) One main source
3) Multiple sources like website, Telegram, Facebook Ads, WhatsApp`
  },
  {
    key: "daily_leads",
    text: `Question 4/10
How many leads/messages do you receive per day?

1) 0–5
2) 6–20
3) 20+`
  },
  {
    key: "budget",
    text: `Question 5/10
What is your budget for this project?

1) No budget yet
2) $100–$300
3) $300+`
  },
  {
    key: "timeline",
    text: `Question 6/10
When do you want to start?

1) Not sure
2) This month
3) This week / ASAP`
  },
  {
    key: "decision_maker",
    text: `Question 7/10
Are you the decision maker?

1) No
2) Partly / need approval
3) Yes`
  },
  {
    key: "current_tools",
    text: `Question 8/10
Do you already use tools like Google Sheets, CRM, Email, Telegram, or WhatsApp?

1) No tools
2) Some tools
3) Yes, and I want them connected`
  },
  {
    key: "urgency",
    text: `Question 9/10
How important is this problem for your business?

1) Low priority
2) Important
3) Very urgent`
  },
  {
    key: "automation_goal",
    text: `Question 10/10
What do you want the automation to do?

1) Basic auto-reply
2) Collect and organize leads
3) Qualify leads, follow up, and notify sales team`
  }
];

// ===============================
// Option Labels
// ===============================

const optionLabels = {
  business_type: {
    1: "Small/local business",
    2: "Growing business",
    3: "Established business with active sales"
  },
  problem: {
    1: "Just exploring automation",
    2: "Repetitive customer messages",
    3: "Losing leads or sales because of slow follow-up"
  },
  lead_source: {
    1: "Not sure / no regular leads",
    2: "One main source",
    3: "Multiple sources"
  },
  daily_leads: {
    1: "0–5",
    2: "6–20",
    3: "20+"
  },
  budget: {
    1: "No budget yet",
    2: "$100–$300",
    3: "$300+"
  },
  timeline: {
    1: "Not sure",
    2: "This month",
    3: "This week / ASAP"
  },
  decision_maker: {
    1: "No",
    2: "Partly / need approval",
    3: "Yes"
  },
  current_tools: {
    1: "No tools",
    2: "Some tools",
    3: "Yes, and I want them connected"
  },
  urgency: {
    1: "Low priority",
    2: "Important",
    3: "Very urgent"
  },
  automation_goal: {
    1: "Basic auto-reply",
    2: "Collect and organize leads",
    3: "Qualify leads, follow up, and notify sales team"
  }
};

// ===============================
// Helper Functions
// ===============================

function baseOutput(extra) {
  return [
    {
      json: {
        date: new Date().toISOString(),
        chat_id: chatId,
        customer_message: messageText,
        first_name: telegram.message.from.first_name || "",
        username: telegram.message.from.username || "",
        source: "Telegram",
        ...extra
      }
    }
  ];
}

function scoreAnswer(answer) {
  if (answer === 1) return 0;
  if (answer === 2) return 50;
  if (answer === 3) return 100;
  return 0;
}

function getLeadStatus(score) {
  if (score >= 80) return "Hot Lead";
  if (score >= 50) return "Warm Lead";
  return "Weak Lead";
}

function getBuyingIntent(score) {
  if (score >= 80) return "High";
  if (score >= 50) return "Medium";
  return "Low";
}

// ===============================
// Start / Restart Flow
// ===============================

if (startWords.includes(lowerText)) {
  staticData.leadSessions[chatId] = {
    currentQuestion: 0,
    answers: []
  };

  return baseOutput({
    business_type: "",
    need: "Questionnaire started",
    lead_source: "",
    daily_leads: "",
    budget: "Pending",
    timeline: "Pending",
    decision_maker: "",
    current_tools: "",
    buying_intent: "Pending",
    lead_score: 0,
    lead_percentage: "0%",
    lead_status: "Pending",
    documentation_sent: "No",
    sales_summary: "Customer started the 10-question lead qualification flow.",
    customer_reply:
      `Welcome 👋

I will ask you 10 quick questions to understand your request.
Please answer each question with only 1, 2, or 3.

${questions[0].text}

Remaining questions: 9`
  });
}

// ===============================
// No Active Session
// ===============================

if (!staticData.leadSessions[chatId]) {
  return baseOutput({
    business_type: "",
    need: "No active questionnaire",
    lead_source: "",
    daily_leads: "",
    budget: "Unknown",
    timeline: "Unknown",
    decision_maker: "",
    current_tools: "",
    buying_intent: "Unknown",
    lead_score: 0,
    lead_percentage: "0%",
    lead_status: "Weak Lead",
    documentation_sent: "No",
    sales_summary: "Customer sent a message without starting the questionnaire.",
    customer_reply: "Please type hi to start the 10-question lead qualification process."
  });
}

const session = staticData.leadSessions[chatId];

// ===============================
// Qualification Flow
// ===============================

const answer = Number(messageText);

if (![1, 2, 3].includes(answer)) {
  const currentQuestion = questions[session.currentQuestion];

  return baseOutput({
    business_type: "",
    need: "Invalid answer",
    lead_source: "",
    daily_leads: "",
    budget: "Unknown",
    timeline: "Unknown",
    decision_maker: "",
    current_tools: "",
    buying_intent: "Unknown",
    lead_score: 0,
    lead_percentage: "0%",
    lead_status: "Pending",
    documentation_sent: "No",
    sales_summary: "Customer answered with invalid format.",
    customer_reply:
      `Please answer with only 1, 2, or 3.

${currentQuestion.text}

Remaining questions: ${10 - session.currentQuestion - 1}`
  });
}

// Save answer
session.answers.push(answer);
session.currentQuestion += 1;

// Send next question
if (session.currentQuestion < questions.length) {
  const nextQuestion = questions[session.currentQuestion];
  const remaining = questions.length - session.currentQuestion - 1;

  return baseOutput({
    business_type: "",
    need: "Questionnaire in progress",
    lead_source: "",
    daily_leads: "",
    budget: "Pending",
    timeline: "Pending",
    decision_maker: "",
    current_tools: "",
    buying_intent: "Pending",
    lead_score: 0,
    lead_percentage: "0%",
    lead_status: "Pending",
    documentation_sent: "No",
    sales_summary: `Customer answered question ${session.currentQuestion}/10.`,
    customer_reply:
      `Thanks ✅

${nextQuestion.text}

Remaining questions: ${remaining}`
  });
}

// ===============================
// Finished 10 Questions
// ===============================

const answers = session.answers;
delete staticData.leadSessions[chatId];

const answerScores = answers.map(scoreAnswer);
const totalScore = answerScores.reduce((sum, value) => sum + value, 0);
const leadScore = Math.round(totalScore / questions.length);

const leadStatus = getLeadStatus(leadScore);
const buyingIntent = getBuyingIntent(leadScore);

const mapped = {};
questions.forEach((question, index) => {
  mapped[question.key] = optionLabels[question.key][answers[index]];
});

const salesSummary = `Lead completed the 10-question qualification flow.

Lead Score: ${leadScore}%
Lead Status: ${leadStatus}

Business Type: ${mapped.business_type}
Problem: ${mapped.problem}
Lead Source: ${mapped.lead_source}
Daily Leads: ${mapped.daily_leads}
Budget: ${mapped.budget}
Timeline: ${mapped.timeline}
Decision Maker: ${mapped.decision_maker}
Current Tools: ${mapped.current_tools}
Urgency: ${mapped.urgency}
Automation Goal: ${mapped.automation_goal}`;

const customerReply =
  leadScore >= 70
    ? `Thank you. Your request has been received successfully.

A member of our sales team will contact you within the next 24 hours to discuss your requirements and the next steps.`
    : `Thank you for your answers.

Our team will review your request and get back to you if your requirements match our service.`;

return baseOutput({
  business_type: mapped.business_type,
  need: mapped.automation_goal,
  lead_source: mapped.lead_source,
  daily_leads: mapped.daily_leads,
  budget: mapped.budget,
  timeline: mapped.timeline,
  decision_maker: mapped.decision_maker,
  current_tools: mapped.current_tools,
  buying_intent: buyingIntent,
  lead_score: leadScore,
  lead_percentage: `${leadScore}%`,
  lead_status: leadStatus,
  documentation_sent: leadScore >= 70 ? "Yes" : "No",
  sales_summary: salesSummary,
  customer_reply: customerReply
});

